import CryptoKit
import Foundation
import Testing
import VaultCore
@testable import SharingKit

/// Known-answer tests for `fxvault-team/v1` (v0.5.0) against Fixtures/team_kat.json, generated by
/// Fixtures/kat/crosscheck.py (`--write-team`) from RFC 7748, RFC 5869 and RFC 8032. Ed25519
/// signatures there are deterministic; CryptoKit signs with randomness, so the signatures are
/// verified here rather than reproduced.
@Suite("Teammate known-answer vectors")
struct TeamKATTests {
    struct Document: Decodable {
        let inputs: [String: Inputs]
        let outputs: [String: String]

        enum Inputs: Decodable {
            case text(String)
            case number(Int64)

            init(from decoder: any Decoder) throws {
                let container = try decoder.singleValueContainer()
                if let number = try? container.decode(Int64.self) {
                    self = .number(number)
                } else {
                    self = .text(try container.decode(String.self))
                }
            }
        }

        static func load(_ name: String = "team_kat.json") throws -> Document {
            try JSONDecoder().decode(Document.self, from: Fixtures.data(name))
        }

        func input(_ key: String) throws -> String {
            guard case .text(let text) = try #require(inputs[key]) else { throw KATError.wrongType }
            return text
        }

        func number(_ key: String) throws -> Int64 {
            guard case .number(let number) = try #require(inputs[key]) else { throw KATError.wrongType }
            return number
        }

        func bytes(_ key: String) throws -> Data {
            try #require(Data(hex: try input(key)))
        }

        func output(_ key: String) throws -> String {
            try #require(outputs[key])
        }

        func outputBytes(_ key: String) throws -> Data {
            try #require(Data(hex: try output(key)))
        }

        func device(_ prefix: String) throws -> TeamDeviceKeys {
            TeamDeviceKeys(
                signing: try Curve25519.Signing.PrivateKey(rawRepresentation: try bytes("\(prefix)SigningSeed")),
                agreement: try Curve25519.KeyAgreement.PrivateKey(rawRepresentation: try bytes("\(prefix)AgreementKey")),
                announceKey: try bytes("\(prefix)AnnounceKey")
            )
        }
    }

    enum KATError: Error {
        case wrongType
    }

    @Test func labelsAndPreamblesArePinned() throws {
        let kat = try Document.load()
        #expect(try kat.input("pairLabelPrefix") == TeamProtocol.pairLabelPrefix)
        #expect(try kat.input("teamLabelPrefix") == TeamProtocol.labelPrefix)
        #expect(TeamService.team.preamble.hex == (try kat.output("PREAMBLE_team")))
        #expect(TeamService.chat.preamble.hex == (try kat.output("PREAMBLE_chat")))
        let python = try String(contentsOf: Fixtures.url("kat/crosscheck.py"), encoding: .utf8)
        #expect(python.contains("TEAM_PREFIX = b'fxvault/team/v1'"))
        #expect(python.contains("PAIR_PREFIX = b'fxvault/pair/v1'"))
    }

    @Test func deviceIDsCardsAndPseudonyms() throws {
        let kat = try Document.load()
        let ana = try kat.device("ana")
        let ben = try kat.device("ben")
        #expect(ana.signingPublicKey.hex == (try kat.output("ana_signing_pk")))
        #expect(ana.agreementPublicKey.hex == (try kat.output("ana_agreement_pk")))
        #expect(ben.signingPublicKey.hex == (try kat.output("ben_signing_pk")))
        #expect(ana.deviceID.hex == (try kat.output("ana_device_id")))
        #expect(ben.deviceID.hex == (try kat.output("ben_device_id")))

        let card = ana.card(
            login: try kat.input("anaLogin"),
            displayName: try kat.input("anaDisplayName"),
            macName: try kat.input("anaMacName")
        )
        #expect(card.encoded().hex == (try kat.output("ana_card")))
        #expect(try TeamCardModel.decode(try kat.outputBytes("ana_card")) == card)

        let window = try kat.number("window")
        #expect(TeamPseudonym.name(announceKey: ana.announceKey, window: window) == (try kat.output("ana_pseudonym")))
        #expect(TeamPseudonym.name(announceKey: ana.announceKey, window: window + 1) == (try kat.output("ana_pseudonym_next")))
    }

    @Test func pairedHandshakeTranscriptKeysAndAuth() throws {
        let kat = try Document.load()
        let ana = try kat.device("ana")
        let ben = try kat.device("ben")
        let ephI = try Curve25519.KeyAgreement.PrivateKey(rawRepresentation: try kat.bytes("ephI"))
        let ephR = try Curve25519.KeyAgreement.PrivateKey(rawRepresentation: try kat.bytes("ephR"))
        let nonceI = try kat.bytes("nI")
        let nonceR = try kat.bytes("nR")
        #expect(ephI.publicKey.rawRepresentation.hex == (try kat.output("ephPkI")))
        #expect(ephR.publicKey.rawRepresentation.hex == (try kat.output("ephPkR")))

        let hello = TeamSessionMachine.hello(.helloInitiator, publicKey: ephI.publicKey.rawRepresentation, nonce: nonceI)
        #expect(hello.hex == (try kat.output("HELLO_I")))
        let secret = try NearbyCrypto.sharedSecret(privateKey: ephI, peerPublicKey: ephR.publicKey.rawRepresentation)
        #expect(secret.withUnsafeBytes { Data($0) }.hex == (try kat.output("shared_secret")))
        let th = TeamSessionMachine.transcriptHash(
            publicKeyI: ephI.publicKey.rawRepresentation,
            nonceI: nonceI,
            publicKeyR: ephR.publicKey.rawRepresentation,
            nonceR: nonceR
        )
        #expect(th.hex == (try kat.output("TH")))
        let keys = NearbyCrypto.deriveSession(sharedSecret: secret, transcriptHash: th, labels: .team)
        #expect(keys.initiatorToResponder.withUnsafeBytes { Data($0) }.hex == (try kat.output("k_i2r")))
        #expect(keys.responderToInitiator.withUnsafeBytes { Data($0) }.hex == (try kat.output("k_r2i")))

        let authI = TeamSessionMachine.authMessage(type: .authInitiator, transcriptHash: th, initiator: ana.deviceID, responder: ben.deviceID)
        let authR = TeamSessionMachine.authMessage(type: .authResponder, transcriptHash: th, initiator: ana.deviceID, responder: ben.deviceID)
        #expect(authI.hex == (try kat.output("auth_i_message")))
        #expect(authR.hex == (try kat.output("auth_r_message")))
        let anaCard = ana.card(login: "", displayName: "", macName: "")
        let benCard = ben.card(login: "", displayName: "", macName: "")
        #expect(anaCard.isValidSignature(try kat.outputBytes("auth_i_signature"), for: authI))
        #expect(benCard.isValidSignature(try kat.outputBytes("auth_r_signature"), for: authR))
        #expect(!benCard.isValidSignature(try kat.outputBytes("auth_i_signature"), for: authI))
        #expect(anaCard.isValidSignature(try ana.sign(authI), for: authI), "CryptoKit's own signature verifies too")

        var channel = NearbyChannel(role: .responder, keys: keys)
        let (type, body) = try channel.open(try kat.outputBytes("AUTH_I_i2r_seq0"))
        #expect(type == TeamMessageType.authInitiator.rawValue)
        #expect(body.hex == ana.deviceID.hex + (try kat.output("auth_i_signature")))
        var sender = NearbyChannel(role: .initiator, keys: keys)
        _ = try sender.seal(TeamMessageType.authInitiator.rawValue, body)
        #expect(try sender.seal(TeamMessageType.ping.rawValue, Data()).hex == (try kat.output("PING_i2r_seq1")))
    }

    @Test func pairingCommitmentTranscriptAndCardSignature() throws {
        let kat = try Document.load()
        let ana = try kat.device("ana")
        let ephI = try Curve25519.KeyAgreement.PrivateKey(rawRepresentation: try kat.bytes("ephI"))
        let ephR = try Curve25519.KeyAgreement.PrivateKey(rawRepresentation: try kat.bytes("ephR"))
        let commitment = NearbyCrypto.commitment(
            maxVersion: 1,
            suite: 1,
            publicKey: ephI.publicKey.rawRepresentation,
            nonce: try kat.bytes("nI"),
            labels: .pair
        )
        #expect(commitment.hex == (try kat.output("C_pair")))
        let th = NearbyCrypto.transcriptHash(
            NearbyTranscriptModel(
                maxVersionI: 1,
                maxVersionR: 1,
                version: 1,
                suiteI: 1,
                suiteR: 1,
                commitment: commitment,
                publicKeyI: ephI.publicKey.rawRepresentation,
                nonceI: try kat.bytes("nI"),
                nameI: Data("Ana's Mac".utf8),
                publicKeyR: ephR.publicKey.rawRepresentation,
                nonceR: try kat.bytes("nR"),
                nameR: Data("Ben's Mac".utf8)
            ),
            labels: .pair
        )
        #expect(th.hex == (try kat.output("TH_pair")))
        let card = try kat.outputBytes("ana_card")
        let message = TeamPairingMachine.signedCardMessage(role: .initiator, transcriptHash: th, card: card)
        #expect(message.hex == (try kat.output("card_message_i")))
        let anaCard = ana.card(login: "", displayName: "", macName: "")
        #expect(anaCard.isValidSignature(try kat.outputBytes("card_signature_i"), for: message))
        let reflected = TeamPairingMachine.signedCardMessage(role: .responder, transcriptHash: th, card: card)
        #expect(!anaCard.isValidSignature(try kat.outputBytes("card_signature_i"), for: reflected), "the role is bound")

        let teamTH = try kat.outputBytes("TH")
        #expect(NearbyChatMachine.identMessage(role: .initiator, transcriptHash: teamTH).hex == (try kat.output("chat_ident_message_i")))
    }
}
